INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was regelt das BDSG für Fachinformatiker?', 2, '[{"text": "Schutz personenbezogener Daten", "correct": true, "because": "Datenschutzgesetz"}, {"text": "Arbeitszeiten", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich als Fachinformatiker mit dem BDSG?', 3, '[{"text": "Datenschutz sicherstellen", "correct": true, "because": "Schutz der Privatsphäre"}, {"text": "Systemleistung verbessern", "correct": false, "because": "Kein primäres Ziel"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum BDSG?', 5, '[{"text": "Datenerhebungsvorschriften", "correct": true, "because": "Regelt Erhebung"}, {"text": "Rechte der Betroffenen", "correct": true, "because": "z.B. Auskunft"}, {"text": "Marketingstrategien", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BDSG ergänzt die DSGVO. b) Es gilt nur für öffentliche Stellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Privatwirtschaft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim BDSG als Fachinformatiker?', 4, '[{"text": "Datensicherheitsmaßnahmen", "correct": false, "because": "Pflicht"}, {"text": "Einwilligung der Betroffenen", "correct": false, "because": "Notwendig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das BDSG die Verarbeitung personenbezogener Daten regelt?', 2, '[{"text": "Ja", "correct": true, "because": "Kern des Gesetzes"}, {"text": "Nein", "correct": false, "because": "Hauptzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflicht hat ein Fachinformatiker laut BDSG?', 3, '[{"text": "Datensicherheit gewährleisten", "correct": true, "because": "§ 9 BDSG"}, {"text": "Arbeitszeiten planen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung des BDSG?', 5, '[{"text": "Technische Schutzmaßnahmen", "correct": true, "because": "z.B. Verschlüsselung"}, {"text": "Organisatorische Maßnahmen", "correct": true, "because": "z.B. Zugriffskontrolle"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das BDSG verlangt Datenschutzbeauftragte in großen Firmen. b) Es gilt nur für papierbasierte Daten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch digitale Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim BDSG unwichtig?', 4, '[{"text": "Datenschutzvorschriften", "correct": false, "because": "Kern des Gesetzes"}, {"text": "Betroffenenrechte", "correct": false, "because": "Pflicht"}, {"text": "Farbe der Serverräume", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Fachinformatiker das BDSG kennen?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht bei Datenverarbeitung"}, {"text": "Nein", "correct": false, "because": "Relevante Vorschrift"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Einhaltung des BDSG?', 4, '[{"text": "Rechtssicherheit", "correct": true, "because": "Vermeidet Bußgelder"}, {"text": "Vertrauen der Nutzer", "correct": true, "because": "Datenschutz stärkt"}, {"text": "Schnellere Systeme", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das BDSG nur für große Firmen gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Firmen betroffen"}, {"text": "Ja", "correct": false, "because": "Allgemein gültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim BDSG?', 3, '[{"text": "Datensicherheit", "correct": true, "because": "Schutz der Daten"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BDSG verlangt technische Maßnahmen. b) Es gilt nur für öffentliche Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch private Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Nichtbeachtung des BDSG?', 5, '[{"text": "Bußgelder", "correct": true, "because": "Bis zu 20 Mio. €"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kunden ziehen sich zurück"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim BDSG?', 3, '[{"text": "Datensicherung umsetzen", "correct": true, "because": "Technische Maßnahmen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker das BDSG digital umsetzen?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Zugriffskontrollen"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht gewährt das BDSG Betroffenen?', 4, '[{"text": "Auskunftsrecht", "correct": true, "because": "§ 34 BDSG"}, {"text": "Arbeitszeitregelung", "correct": false, "because": "Kein Bezug"}, {"text": "Mindestlohn", "correct": false, "because": "Anderes Gesetz"}]');
